SELECT CAST(COUNT(DISTINCT CASE WHEN a.dischtime IS NOT NULL AND a.dischtime <= a.admittime + INTERVAL '30 days' THEN a.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS readmission_rate, AVG(CASE WHEN a.dischtime IS NOT NULL AND a.dischtime <= a.admittime + INTERVAL '30 days' THEN (a.dischtime - a.admittime) END) AS avg_los_readmitted, AVG(CASE WHEN a.dischtime IS NOT NULL AND a.dischtime > a.admittime + INTERVAL '30 days' THEN (a.dischtime - a.admittime) END) AS avg_los_not_readmitted, COUNT(DISTINCT CASE WHEN (a.dischtime - a.admittime) > INTERVAL '5 days' THEN a.subject_id END) * 100.0 / NULLIF(COUNT(DISTINCT a.subject_id), 0) AS percentage_of_stays_over_5_days FROM admissions a JOIN patients p ON a.subject_id = p.subject_id WHERE p.gender = 'M' AND p.anchor_year BETWEEN 76 AND 86 AND a.admission_type = 'ED' AND a.edregtime IS NOT NULL AND a.edouttime IS NOT NULL AND p.insurance = 'Medicare' AND p.anchor_age = 81;